import type { Frontmatter } from './frontmatter';

export interface Page {
  slug: string;
  title: string;
  date?: string;
  tags: string[];
  contentHtml: string;
  sourcePath: string;
  outputPath: string;
  template?: string;
  layout?: string;
  data: Frontmatter;
  content?: string;
  html?: string;
}

export interface BuildOptions {
  content: string;
  output: string;
  templates?: string;
  config?: string | false;
}

import type { BuildOptions, Page } from './types';
import type { SsgConfig } from './config';

export interface PluginContext {
  options: BuildOptions;
  config: SsgConfig;
  cwd: string;
  [key: string]: unknown;
}

export interface Plugin {
  name: string;
  onStart?(context: PluginContext): void | Promise<void>;
  beforeBuild?(context: PluginContext): void | Promise<void>;
  onFile?(page: Page, context: PluginContext): Page | void | Promise<Page | void>;
  afterBuild?(pages: Page[], context: PluginContext): void | Promise<void>;
  onEnd?(context: PluginContext): void | Promise<void>;
}

export function isPlugin(value: unknown): value is Plugin {
  if (!value || typeof value !== 'object') {
    return false;
  }
  const candidate = value as Plugin;
  return (
    typeof candidate.name === 'string' &&
    (typeof candidate.onStart === 'function' ||
      typeof candidate.beforeBuild === 'function' ||
      typeof candidate.onFile === 'function' ||
      typeof candidate.afterBuild === 'function' ||
      typeof candidate.onEnd === 'function')
  );
}

import path from 'path';
import { promises as fs, existsSync, readFileSync } from 'fs';
import { Module } from 'module';
import { pathToFileURL } from 'url';

let typescript: typeof import('typescript') | null | undefined;

function getTypescript(): typeof import('typescript') | undefined {
  if (typescript === undefined) {
    try {
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      typescript = require('typescript') as typeof import('typescript');
    } catch {
      typescript = null;
    }
  }
  return typescript ?? undefined;
}

let tsHookInstalled = false;

function ensureTsRequireHook(): void {
  if (tsHookInstalled) {
    return;
  }
  tsHookInstalled = true;

  const originalResolve = Module._resolveFilename;

  const resolveCandidates = (
    request: string,
    parent?: Module | null
  ): string | null => {
    if (!request.startsWith('.') && !path.isAbsolute(request)) {
      return null;
    }
    const base = parent ? path.dirname(parent.filename) : process.cwd();
    const abs = path.resolve(base, request);
    const candidates = [
      abs,
      `${abs}.ts`,
      `${abs}.tsx`,
      `${abs}.mts`,
      `${abs}.js`,
      `${abs}.cjs`,
      `${abs}.json`,
      path.join(abs, 'index.ts'),
      path.join(abs, 'index.js'),
      path.join(abs, 'index.json'),
    ];
    for (const candidate of candidates) {
      if (existsSync(candidate)) {
        return candidate;
      }
    }
    return null;
  };

  Module._resolveFilename = function (request, parent, isMain, options) {
    const resolved = resolveCandidates(request, parent);
    if (resolved) {
      return resolved;
    }
    return originalResolve.call(this, request, parent, isMain, options);
  };

  const compile = (module: Module, filename: string): void => {
    const ts = getTypescript();
    if (!ts) {
      throw new Error(
        'Loading a TypeScript config or plugin requires the "typescript" package to be installed.'
      );
    }
    const source = readFileSync(filename, 'utf8');
    const result = ts.transpileModule(source, {
      compilerOptions: {
        module: ts.ModuleKind.CommonJS,
        target: ts.ScriptTarget.ES2020,
        esModuleInterop: true,
        allowSyntheticDefaultImports: true,
        moduleResolution: ts.ModuleResolutionKind.NodeJs,
        skipLibCheck: true,
      },
      fileName: filename,
    });
    module._compile(result.outputText, filename);
  };

  // eslint-disable-next-line @typescript-eslint/no-var-requires
  const extensions = (require as { extensions: Record<string, unknown> }).extensions;
  extensions['.ts'] = compile;
  extensions['.tsx'] = compile;
  extensions['.mts'] = compile;
}

export async function loadModule(filePath: string): Promise<unknown> {
  const ext = path.extname(filePath).toLowerCase();
  if (ext === '.mjs') {
    const mod = await import(pathToFileURL(filePath).href);
    return (mod as { default?: unknown }).default ?? mod;
  }
  if (ext === '.ts' || ext === '.tsx' || ext === '.mts') {
    ensureTsRequireHook();
  }
  if (ext === '.json') {
    return JSON.parse(await fs.readFile(filePath, 'utf8'));
  }
  // eslint-disable-next-line @typescript-eslint/no-var-requires
  return require(filePath);
}

import path from 'path';
import { existsSync } from 'fs';
import type { Plugin } from './plugin';
import { isPlugin } from './plugin';
import { loadModule } from './loaders';

export interface SsgConfig {
  plugins?: Array<Plugin | string>;
}

export function defineConfig(config: SsgConfig): SsgConfig {
  return config;
}

export function normalizeConfig(raw: unknown): SsgConfig {
  if (!raw || typeof raw !== 'object') {
    return {};
  }
  const config = raw as SsgConfig;
  if (config.plugins == null) {
    return {};
  }
  const plugins = Array.isArray(config.plugins) ? config.plugins : [config.plugins];
  return { plugins };
}

const CONFIG_FILENAMES = [
  'ssg.config.ts',
  'ssg.config.mts',
  'ssg.config.js',
  'ssg.config.cjs',
  'ssg.config.mjs',
  'ssg.config.json',
];

export async function loadConfig(cwd: string = process.cwd()): Promise<SsgConfig> {
  for (const name of CONFIG_FILENAMES) {
    const filePath = path.join(cwd, name);
    if (!existsSync(filePath)) {
      continue;
    }
    try {
      const loaded = await loadModule(filePath);
      const exported = unwrapDefault(loaded);
      const resolved = typeof exported === 'function' ? await exported() : exported;
      return normalizeConfig(resolved);
    } catch {
      continue;
    }
  }
  return {};
}

export async function loadConfigFile(filePath: string): Promise<SsgConfig> {
  const loaded = await loadModule(path.resolve(filePath));
  const exported = unwrapDefault(loaded);
  const resolved = typeof exported === 'function' ? await exported() : exported;
  return normalizeConfig(resolved);
}

function unwrapDefault(mod: unknown): unknown {
  if (mod && typeof mod === 'object' && 'default' in (mod as Record<string, unknown>)) {
    return (mod as { default: unknown }).default;
  }
  return mod;
}

const BUILTIN_PLUGIN_NAMES = new Set(['markdown', 'template', 'devServer']);

export async function resolvePlugins(
  entries: Array<Plugin | string> | undefined,
  baseDir: string
): Promise<Plugin[]> {
  const resolved: Plugin[] = [];
  for (const entry of entries ?? []) {
    for (const plugin of await resolvePluginEntry(entry, baseDir)) {
      resolved.push(plugin);
    }
  }
  return resolved;
}

async function resolvePluginEntry(
  entry: Plugin | string,
  baseDir: string
): Promise<Plugin[]> {
  if (typeof entry === 'string') {
    if (BUILTIN_PLUGIN_NAMES.has(entry)) {
      return [];
    }
    const filePath = resolvePluginPath(baseDir, entry);
    if (!filePath) {
      return [];
    }
    try {
      return await flattenPluginExport(await loadModule(filePath));
    } catch {
      return [];
    }
  }
  if (typeof entry === 'function') {
    return flattenPluginExport(await (entry as () => unknown)());
  }
  if (isPlugin(entry)) {
    return [entry];
  }
  return [];
}

function resolvePluginPath(baseDir: string, entry: string): string | undefined {
  const abs = path.isAbsolute(entry) ? entry : path.resolve(baseDir, entry);
  const candidates = [
    abs,
    `${abs}.ts`,
    `${abs}.tsx`,
    `${abs}.js`,
    `${abs}.cjs`,
    `${abs}.mjs`,
    path.join(abs, 'index.ts'),
    path.join(abs, 'index.js'),
    path.join(abs, 'index.json'),
  ];
  for (const candidate of candidates) {
    if (existsSync(candidate)) {
      return candidate;
    }
  }
  return undefined;
}

async function flattenPluginExport(mod: unknown): Promise<Plugin[]> {
  const exported = unwrapDefault(mod);
  if (typeof exported === 'function') {
    return flattenPluginExport(await (exported as () => unknown)());
  }
  if (Array.isArray(exported)) {
    const out: Plugin[] = [];
    for (const item of exported) {
      out.push(...(await flattenPluginExport(item)));
    }
    return out;
  }
  if (isPlugin(exported)) {
    return [exported];
  }
  return [];
}

import type { Plugin } from '../plugin';
import type { Page } from '../types';
import { markdownToHtml } from '../markdown';

export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  onFile(page: Page): Page {
    page.contentHtml = markdownToHtml(page.content ?? '');
    return page;
  }
}

import type { Plugin } from '../plugin';
import type { Page } from '../types';
import { TemplateEngine } from '../templates';
import { renderPage, renderIndex } from '../render';

export class TemplatePlugin implements Plugin {
  readonly name = 'template';
  readonly engine: TemplateEngine;

  constructor(templatesDir: string) {
    this.engine = new TemplateEngine(templatesDir);
  }

  async beforeBuild(): Promise<void> {
    await this.engine.load();
  }

  renderPage(page: Page): string {
    return renderPage(page, this.engine);
  }

  renderIndex(pages: Page[]): string {
    return renderIndex(pages, this.engine);
  }
}

export function liveReloadScript(): string {
  return [
    '<script data-ssg-live-reload>',
    '(function(){',
    '  var ws=new WebSocket("ws://"+location.host);',
    '  ws.onmessage=function(e){ if(e.data==="reload"){ location.reload(); } };',
    '})();',
    '</script>',
  ].join('\n');
}

export function injectLiveReload(html: string): string {
  const script = liveReloadScript();
  if (/<\/body>/i.test(html)) {
    return html.replace(/<\/body>/i, `${script}\n</body>`);
  }
  return `${html}\n${script}\n`;
}

import { createServer, IncomingMessage, ServerResponse } from 'http';
import type { AddressInfo } from 'net';
import { promises as fs } from 'fs';
import path from 'path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import type { Plugin } from '../plugin';
import type { SsgEngine } from '../engine';
import type { ServeOptions, DevServer } from '../serve';
import { injectLiveReload } from '../liveReload';

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'application/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};

export class DevServerPlugin implements Plugin {
  readonly name = 'devServer';

  constructor(private readonly engine: SsgEngine) {}

  async start(options: ServeOptions): Promise<DevServer> {
    const contentDir = path.resolve(options.content);
    const outputDir = path.resolve(options.output);
    const templatesDir = options.templates ?? './templates';
    const requestedPort = options.port ?? 3000;

    const server = createServer((req, res) => {
      void handleRequest(req, res, outputDir);
    });

    const wss = new WebSocketServer({ server });

    let building = false;
    let queued = false;

    const broadcastReload = (): void => {
      for (const client of wss.clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send('reload');
        }
      }
    };

    const rebuild = async (): Promise<void> => {
      if (building) {
        queued = true;
        return;
      }
      building = true;
      try {
        await this.engine.run();
        broadcastReload();
      } finally {
        building = false;
        if (queued) {
          queued = false;
          await rebuild();
        }
      }
    };

    const watcher = chokidar.watch([contentDir, templatesDir], {
      ignoreInitial: true,
    });

    let debounceTimer: NodeJS.Timeout | null = null;
    const scheduleRebuild = (): void => {
      if (debounceTimer) {
        clearTimeout(debounceTimer);
      }
      debounceTimer = setTimeout(() => {
        debounceTimer = null;
        void rebuild();
      }, 50);
    };

    watcher.on('add', scheduleRebuild);
    watcher.on('change', scheduleRebuild);
    watcher.on('unlink', scheduleRebuild);
    watcher.on('addDir', scheduleRebuild);
    watcher.on('unlinkDir', scheduleRebuild);

    await rebuild();

    await new Promise<void>((resolve, reject) => {
      server.once('error', reject);
      server.listen(requestedPort, () => {
        server.removeListener('error', reject);
        resolve();
      });
    });

    const address = server.address() as AddressInfo;
    const port = address.port;

    return {
      port,
      reload: broadcastReload,
      async close(): Promise<void> {
        if (debounceTimer) {
          clearTimeout(debounceTimer);
          debounceTimer = null;
        }
        await watcher.close();
        for (const client of wss.clients) {
          client.terminate();
        }
        await new Promise<void>((resolve) => {
          wss.close(() => resolve());
        });
        await new Promise<void>((resolve, reject) => {
          server.close((err) => (err ? reject(err) : resolve()));
        });
      },
    };
  }
}

async function handleRequest(
  req: IncomingMessage,
  res: ServerResponse,
  outputDir: string
): Promise<void> {
  const rawUrl = (req.url ?? '/').split('?')[0];
  const urlPath = decodeURIComponent(rawUrl);

  let filePath: string;
  if (urlPath === '/' || urlPath === '') {
    filePath = path.join(outputDir, 'index.html');
  } else {
    filePath = path.resolve(outputDir, urlPath.slice(1));
  }

  const relative = path.relative(outputDir, filePath);
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Forbidden');
    return;
  }

  try {
    const stat = await fs.stat(filePath);
    if (stat.isDirectory()) {
      filePath = path.join(filePath, 'index.html');
    }
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not found');
    return;
  }

  let content: Buffer;
  try {
    content = await fs.readFile(filePath);
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
    res.end('Not found');
    return;
  }

  const ext = path.extname(filePath).toLowerCase();
  const contentType = MIME_TYPES[ext] ?? 'application/octet-stream';

  if (ext === '.html') {
    content = Buffer.from(injectLiveReload(content.toString('utf8')), 'utf8');
  }

  res.writeHead(200, { 'Content-Type': contentType });
  res.end(content);
}

import { promises as fs } from 'fs';
import path from 'path';
import { parseFrontmatter, normalizeTags } from './frontmatter';
import type { BuildOptions, Page } from './types';
import type { Plugin, PluginContext } from './plugin';
import type { SsgConfig } from './config';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';

const MARKDOWN_EXT = /\.(md|markdown)$/i;

async function findMarkdownFiles(dir: string): Promise<string[]> {
  const results: string[] = [];
  let entries;
  try {
    entries = await fs.readdir(dir, { withFileTypes: true });
  } catch {
    return results;
  }

  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...(await findMarkdownFiles(full)));
    } else if (entry.isFile() && MARKDOWN_EXT.test(entry.name)) {
      results.push(full);
    }
  }
  return results;
}

function slugFor(contentDir: string, filePath: string): string {
  const relative = path.relative(contentDir, filePath);
  const withoutExt = relative.replace(MARKDOWN_EXT, '');
  return withoutExt.split(path.sep).join('/');
}

function titleFor(slug: string, data: { title?: string }): string {
  if (data.title && data.title.trim()) {
    return data.title.trim();
  }
  const segments = slug.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? slug;
}

export interface EngineOptions extends BuildOptions {
  plugins?: Plugin[];
}

export class SsgEngine {
  readonly options: EngineOptions;
  readonly config: SsgConfig;
  readonly plugins: Plugin[];
  readonly markdown: MarkdownPlugin;
  readonly template: TemplatePlugin;

  private readonly context: PluginContext;
  private pages: Page[] = [];

  constructor(options: EngineOptions, config: SsgConfig, plugins: Plugin[]) {
    this.options = options;
    this.config = config;
    this.markdown = new MarkdownPlugin();
    this.template = new TemplatePlugin(options.templates ?? './templates');
    this.plugins = [this.markdown, this.template, ...plugins];
    this.context = {
      options,
      config,
      cwd: process.cwd(),
    };
  }

  get builtPages(): Page[] {
    return this.pages;
  }

  async run(): Promise<Page[]> {
    const ctx = this.context;

    for (const plugin of this.plugins) {
      if (plugin.onStart) {
        await plugin.onStart(ctx);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.beforeBuild) {
        await plugin.beforeBuild(ctx);
      }
    }

    const contentDir = path.resolve(this.options.content);
    const outputDir = path.resolve(this.options.output);
    const files = (await findMarkdownFiles(contentDir)).sort();

    const pages: Page[] = [];
    for (const file of files) {
      const raw = await fs.readFile(file, 'utf8');
      const { data, body } = parseFrontmatter(raw);
      const slug = slugFor(contentDir, file);

      let page: Page = {
        slug,
        title: titleFor(slug, data),
        date: data.date,
        tags: normalizeTags(data.tags),
        contentHtml: '',
        content: body,
        sourcePath: file,
        outputPath: path.join(outputDir, `${slug}.html`),
        template: data.template,
        layout: data.layout,
        data,
      };

      for (const plugin of this.plugins) {
        if (plugin.onFile) {
          const result = await plugin.onFile(page, ctx);
          if (result) {
            page = result;
          }
        }
      }

      pages.push(page);
    }

    this.pages = pages;

    await fs.mkdir(outputDir, { recursive: true });

    for (const page of pages) {
      await fs.mkdir(path.dirname(page.outputPath), { recursive: true });
      const html = page.html ?? this.template.renderPage(page);
      await fs.writeFile(page.outputPath, html, 'utf8');
    }

    await fs.writeFile(
      path.join(outputDir, 'index.html'),
      this.template.renderIndex(pages),
      'utf8'
    );

    for (const plugin of this.plugins) {
      if (plugin.afterBuild) {
        await plugin.afterBuild(pages, ctx);
      }
    }

    for (const plugin of this.plugins) {
      if (plugin.onEnd) {
        await plugin.onEnd(ctx);
      }
    }

    return pages;
  }
}

import type { BuildOptions, Page } from './types';
import type { Plugin } from './plugin';
import type { SsgConfig } from './config';
import { loadConfig, loadConfigFile, resolvePlugins } from './config';
import { SsgEngine } from './engine';

export interface BuildInput extends BuildOptions {
  plugins?: Plugin[];
}

async function resolveBuildConfig(options: BuildInput): Promise<SsgConfig> {
  if (options.config === false) {
    return {};
  }
  if (typeof options.config === 'string') {
    return loadConfigFile(options.config);
  }
  return loadConfig(process.cwd());
}

export async function build(options: BuildInput): Promise<Page[]> {
  const config = await resolveBuildConfig(options);
  const configPlugins = await resolvePlugins(config.plugins, process.cwd());
  const plugins = [...configPlugins, ...(options.plugins ?? [])];

  const engine = new SsgEngine(options, config, plugins);
  return engine.run();
}

import type { Plugin } from './plugin';
