  port?: number;
  config?: string | false;
  plugins?: Plugin[];
}

export interface DevServer {
  port: number;
  reload(): void;
  close(): Promise<void>;
}

async function resolveServeConfig(options: ServeOptions): Promise<SsgConfig> {
  if (options.config === false) {
    return {};
  }
  if (typeof options.config === 'string') {
    return loadConfigFile(options.config);
  }
  return loadConfig(process.cwd());
}

export async function serve(options: ServeOptions): Promise<DevServer> {
  const config = await resolveServeConfig(options);
  const configPlugins = await resolvePlugins(config.plugins, process.cwd());
  const plugins = [...configPlugins, ...(options.plugins ?? [])];

  const engine = new SsgEngine(options, config, plugins);
  const devServer = new DevServerPlugin(engine);
  return devServer.start(options);
}

