import { promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import { build, defineConfig, SsgEngine, MarkdownPlugin, TemplatePlugin, DevServerPlugin } from '../src';
import type { Plugin } from '../src';

async function makeTempDir(): Promise<string> {
  return fs.mkdtemp(path.join(os.tmpdir(), 'ssg-plugin-'));
}

describe('plugin system', () => {
  it('runs hooks in order and transforms files', async () => {
    const contentDir = await makeTempDir();
    const outputDir = await makeTempDir();
    await fs.writeFile(path.join(contentDir, 'a.md'), '# Hello');

    const events: string[] = [];
    const plugin: Plugin = {
      name: 'test',
      onStart() {
        events.push('start');
      },
      beforeBuild() {
        events.push('before');
      },
      onFile(page) {
        events.push('file');
        page.tags.push('extra');
        return page;
      },
      afterBuild() {
        events.push('after');
      },
      onEnd() {
        events.push('end');
      },
    };

    const pages = await build({ content: contentDir, output: outputDir, plugins: [plugin] });

    expect(events).toEqual(['start', 'before', 'file', 'after', 'end']);
    expect(pages[0].tags).toEqual(['extra']);
    expect(pages[0].contentHtml).toContain('<h1>Hello</h1>');
  });

  it('exposes built-in plugins', () => {
    expect(new MarkdownPlugin().name).toBe('markdown');
    expect(new TemplatePlugin('./templates').name).toBe('template');
    expect(typeof SsgEngine).toBe('function');
    expect(DevServerPlugin).toBeDefined();
    expect(defineConfig({ plugins: [] })).toEqual({ plugins: [] });
  });
});

import { promises as fs } from 'fs';
import os from 'os';
import path from 'path';
import { build, loadConfig, resolvePlugins, defineConfig } from '../src';
import type { Plugin } from '../src';

async function makeTempDir(): Promise<string> {
  return fs.mkdtemp(path.join(os.tmpdir(), 'ssg-cfg-'));
}

async function writeFile(filePath: string, contents: string): Promise<void> {
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, contents, 'utf8');
}

describe('config loading', () => {
  it('loads a ts config and a ts plugin module', async () => {
    const root = await makeTempDir();
    const contentDir = path.join(root, 'content');
    const outputDir = path.join(root, 'out');
    await writeFile(path.join(contentDir, 'a.md'), '# Hi');

    const pluginPath = path.join(root, 'plugins', 'my-plugin.ts');
    await writeFile(
      pluginPath,
      `const plugin = {\n` +
        `  name: 'my-plugin',\n` +
        `  onFile(page) { page.title = 'CUSTOM:' + page.title; return page; },\n` +
        `};\n` +
        `export default plugin;\n`
    );

    const configPath = path.join(root, 'ssg.config.ts');
    await writeFile(configPath, `export default { plugins: ['./plugins/my-plugin.ts'] };\n`);

    const pages = await build({
      content: contentDir,
      output: outputDir,
      config: configPath,
    });

    expect(pages[0].title).toBe('CUSTOM:a');
    expect(pages[0].contentHtml).toContain('<h1>Hi</h1>');
  });

  it('loads a json config and resolves plugins', async () => {
    const root = await makeTempDir();
    const configPath = path.join(root, 'ssg.config.json');
    await fs.writeFile(configPath, JSON.stringify({ plugins: [] }));

    const config = await loadConfig(root);
    expect(config).toEqual({ plugins: [] });

    const resolved = await resolvePlugins(config.plugins, root);
    expect(resolved).toEqual([]);
    expect(defineConfig({ plugins: [] })).toEqual({ plugins: [] });
  });
});

